import{_ as t,o,c as a,a3 as d}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"OpenCode Zen","description":"OpenCode Zen 精選モデルゲートウェイ：公式入口、無料モデル一覧、有料説明、MiniTavern での記入。","frontmatter":{"title":"OpenCode Zen","description":"OpenCode Zen 精選モデルゲートウェイ：公式入口、無料モデル一覧、有料説明、MiniTavern での記入。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"OpenCode Zen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenCode Zen 精選モデルゲートウェイ：公式入口、無料モデル一覧、有料説明、MiniTavern での記入。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/free-cloud/opencode-zen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/free-cloud/opencode-zen"}]]},"headers":[],"relativePath":"ja/free-cloud/opencode-zen.md","filePath":"ja/free-cloud/opencode-zen.md","lastUpdated":1787224147000}'),r={name:"ja/free-cloud/opencode-zen.md"};function n(i,e,l,c,s,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h1><p><a href="https://opencode.ai/" target="_blank" rel="noreferrer">OpenCode</a> チーム提供の <strong>AI ゲートウェイ</strong>：精選・検証済みのコーディング向けモデルをリクエスト課金；あわせていくつか <strong>Free（期限／上限内無料）</strong> テキストモデルを提供。OpenCode 以外のクライアントでも共用可（MiniTavern 含む）。公式：<a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">Zen ドキュメント（简体）</a>。</p><blockquote><p>Zen は<strong>純永久無料プラットフォームではない</strong>：多くの旗艦は従量課金で、請求／チャージが必要なことが多い；下の「無料モデル」は枠内の試用向け。政策は公式準拠。</p></blockquote><h2 id="公式と入口" tabindex="-1">公式と入口 <a class="header-anchor" href="#公式と入口" aria-label="Permalink to &quot;公式と入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>リソース</th><th>アドレス</th></tr></thead><tbody><tr><td>Zen 紹介</td><td><a href="https://opencode.ai/en/zen" target="_blank" rel="noreferrer">opencode.ai/zen</a></td></tr><tr><td>ログイン／Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>ドキュメント（简体）</td><td><a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">opencode.ai/docs/zh-cn/zen</a></td></tr><tr><td>モデルメタデータ</td><td><code>https://opencode.ai/zen/v1/models</code></td></tr><tr><td>API Base URL（OpenAI 互換）</td><td><code>https://opencode.ai/zen/v1</code></td></tr></tbody></table><h2 id="無料の取得" tabindex="-1">無料の取得 <a class="header-anchor" href="#無料の取得" aria-label="Permalink to &quot;無料の取得&quot;">​</a></h2><ol><li><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a>（GitHub／Google）でログイン。</li><li>コンソール案内に従い <strong>API Key</strong> を作成。公式フローは請求情報の追記を求めることが多い；無料帯だけ使う場合も、自動チャージがオフか確認し誤課金を避ける。</li><li>MiniTavern で <strong>カスタム (OpenAI)</strong>、Base URL <code>https://opencode.ai/zen/v1</code>、モデルは下の <strong>Free</strong> ID。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td>無料方式</td><td>いくつかのモデルが <strong>Free</strong>（OpenCode 上限内）；フィードバック収集用で、調整・下線の可能性あり</td></tr><tr><td>有料方式</td><td>従量課金；残高が $5 未満だと既定で $20 自動チャージ可（コンソールで変更／オフ）</td></tr><tr><td>カード紐付け</td><td>公式「仕組み」は請求情報の追加を明記；コンソール実態準拠</td></tr><tr><td>プライバシー注意</td><td>無料帯（Big Pickle、MiMo Free、Hy3、Nemotron Free、Muse Contributor Free など）はログでモデル改善の可能性；Nemotron は NVIDIA 体験エンドポイント、機密を送らない</td></tr></tbody></table><p>完全な価格と廃止表は <a href="https://opencode.ai/docs/zh-cn/zen/#%E5%AE%9A%E4%BB%B7" target="_blank" rel="noreferrer">Zen · 価格</a>。</p><h2 id="モデル一覧" tabindex="-1">モデル一覧 <a class="header-anchor" href="#モデル一覧" aria-label="Permalink to &quot;モデル一覧&quot;">​</a></h2><p>モデル ID は <strong>大文字小文字区別</strong>。Zen はベンダーごとに <code>/chat/completions</code>、<code>/responses</code>、<code>/messages</code> または Gemini 専用経路。MiniTavern <strong>カスタム (OpenAI)</strong> は Chat Completions なので、下表の <strong>OpenAI 互換</strong>行を優先。</p><p>完全表は <a href="https://opencode.ai/docs/zh-cn/zen/#%E7%AB%AF%E7%82%B9" target="_blank" rel="noreferrer">Zen · エンドポイント</a>；<code>GET https://opencode.ai/zen/v1/models</code> も可。</p><h3 id="テキスト-·-無料帯-まず試す" tabindex="-1">テキスト · 無料帯（まず試す） <a class="header-anchor" href="#テキスト-·-無料帯-まず試す" aria-label="Permalink to &quot;テキスト · 無料帯（まず試す）&quot;">​</a></h3><p>いずれも <code>…/v1/chat/completions</code>（Muse Contributor Free のみ Responses）。</p><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>mimo-v2.5-free</code></td><td>小米 MiMo V2.5 無料帯</td></tr><tr><td><code>hy3-free</code></td><td>Hy3 Free</td></tr><tr><td><code>big-pickle</code></td><td>ステルスモデル、無料帯</td></tr><tr><td><code>nemotron-3-ultra-free</code></td><td>NVIDIA Nemotron 体験、機密を送らない</td></tr><tr><td><code>nemotron-3.5-lightning-free</code></td><td>同上</td></tr><tr><td><code>muse-spark-1.2-contributor-free</code></td><td>貢献者無料帯；<code>/responses</code> 経路、<strong>MiniTavern 測連は不向きな場合あり</strong>、プロンプトで Meta モデル訓練を許可する場合あり</td></tr></tbody></table><h3 id="テキスト-·-有料だが-openai-互換-任意" tabindex="-1">テキスト · 有料だが OpenAI 互換（任意） <a class="header-anchor" href="#テキスト-·-有料だが-openai-互換-任意" aria-label="Permalink to &quot;テキスト · 有料だが OpenAI 互換（任意）&quot;">​</a></h3><p>チャージ済みで同一 Base URL を使う場合：</p><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>deepseek-v4-flash</code> / <code>deepseek-v4-pro</code></td><td>DeepSeek（Peak／Off-Peak の価格差あり）</td></tr><tr><td><code>glm-5.1</code> / <code>glm-5.2</code> / <code>glm-5</code></td><td>智譜 GLM</td></tr><tr><td><code>kimi-k2.5</code> / <code>kimi-k2.6</code> / <code>kimi-k2.7-code</code> / <code>kimi-k3</code></td><td>Kimi</td></tr><tr><td><code>minimax-m2.5</code> / <code>minimax-m2.7</code> / <code>minimax-m3</code></td><td>MiniMax</td></tr></tbody></table><h3 id="その他プロトコル-minitavern-では注意" tabindex="-1">その他プロトコル（MiniTavern では注意） <a class="header-anchor" href="#その他プロトコル-minitavern-では注意" aria-label="Permalink to &quot;その他プロトコル（MiniTavern では注意）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種別</th><th>例 ID</th><th>エンドポイント種別</th></tr></thead><tbody><tr><td>GPT 系列</td><td><code>gpt-5.5</code>、<code>gpt-5.4-nano</code> など</td><td><code>/zen/v1/responses</code></td></tr><tr><td>Claude 系列</td><td><code>claude-sonnet-4-6</code>、<code>claude-haiku-4-5</code> など</td><td><code>/zen/v1/messages</code></td></tr><tr><td>Gemini 系列</td><td><code>gemini-3-flash</code> など</td><td><code>/zen/v1/models/&lt;id&gt;</code></td></tr></tbody></table><p>上記は MiniTavern 既定の OpenAI Chat Completions と<strong>完全に同一経路ではない</strong>；ロールプレイチャットは無料帯または上表の OpenAI 互換を優先。Claude が必要なら App 内 <strong>Claude(Anthropic)</strong> 公式 Key、または <a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a> など統一 OpenAI ゲートウェイへ。</p><h3 id="画像-動画" tabindex="-1">画像／動画 <a class="header-anchor" href="#画像-動画" aria-label="Permalink to &quot;画像／動画&quot;">​</a></h3><p>Zen ドキュメントの現行一覧は<strong>言語モデル</strong>中心で、<strong>独立の無料生図／動画帯はない</strong>。画像は <a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a> または <a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料の画像生成</a>。</p><h2 id="minitavern-での記入" tabindex="-1">MiniTavern での記入 <a class="header-anchor" href="#minitavern-での記入" aria-label="Permalink to &quot;MiniTavern での記入&quot;">​</a></h2><p>一般手順は <a href="/ultra_guides/ja/manual/model-link">モデル接続</a>。</p><p>経路：<strong>設定 → モデル → モデル接続 → 新規</strong></p><ol><li>プラットフォーム <strong>カスタム (OpenAI)</strong></li><li>Base URL：<code>https://opencode.ai/zen/v1</code></li><li>API Key を貼り付け</li><li>モデル ID に <code>mimo-v2.5-free</code>（または他の Free／chat 互換 ID）</li><li><strong>テスト</strong> → 成功後にデフォルトへ</li></ol><blockquote><p>測連失敗時：GPT Responses／Claude Messages 専用 ID を選んでいないか確認；自動チャージをオフにしてから無料帯を再試行；<a href="/ultra_guides/ja/manual/errors">エラー排錯</a> と照合。</p></blockquote><h2 id="関連章" tabindex="-1">関連章 <a class="header-anchor" href="#関連章" aria-label="Permalink to &quot;関連章&quot;">​</a></h2><ul><li><a href="/ultra_guides/ja/free-cloud/">無料クラウド総覧</a></li><li><a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a> — 1 つの Key で多数の <code>*-free</code> 閉源／開源＋画像</li><li><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/ja/manual/model-link">モデル接続</a></li></ul>',30)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
